import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · 单元 1 复习与自测","description":"L1–L8 原创练习和答案解析。","frontmatter":{"title":"第四册：流利英语 · 单元 1 复习与自测","description":"L1–L8 原创练习和答案解析。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L8 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 1 单词与短语","link":"/life/english/new-concept/book-4/unit-01/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 2：时间、条件与社会系统","link":"/life/english/new-concept/book-4/unit-02/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 1 单词与短语","link":"/life/english/new-concept/book-4/unit-01/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 2：时间、条件与社会系统","link":"/life/english/new-concept/book-4/unit-02/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/review.md","filePath":"life/english/new-concept/book-4/unit-01/review.md"}'),n={name:"life/english/new-concept/book-4/unit-01/review.md"};function r(l,e,i,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第四册-流利英语-·-单元-1-复习与自测" tabindex="-1">第四册：流利英语 · 单元 1 复习与自测 <a class="header-anchor" href="#第四册-流利英语-·-单元-1-复习与自测" aria-label="Permalink to &quot;第四册：流利英语 · 单元 1 复习与自测&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-1-·-推测情态动词与过去事件" tabindex="-1">Lesson 1 · 推测情态动词与过去事件 <a class="header-anchor" href="#lesson-1-·-推测情态动词与过去事件" aria-label="Permalink to &quot;Lesson 1 · 推测情态动词与过去事件&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The marks might have been made by tools, but their origin remains uncertain.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The bone may ___ belonged to a large animal.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 情态动词后接 have + 过去分词，构成对过去的推测。</p></details><p><strong>表达迁移：</strong> 写三句博物馆展签：观察一个破损陶片，提出用途猜想，并说明缺少的证据。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This fragment has a narrow painted edge. It might have belonged to a small bowl. Without the rest of the object, its use remains uncertain.</p><p>先描述可见特征，再用 might have belonged 表推断，最后说明结论边界。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">回看本课</a></p><h2 id="lesson-2-·-数量词与可数性" tabindex="-1">Lesson 2 · 数量词与可数性 <a class="header-anchor" href="#lesson-2-·-数量词与可数性" aria-label="Permalink to &quot;Lesson 2 · 数量词与可数性&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The number of insects was lower in the sheltered garden.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：A number of spiders ___ found near the wall.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> a number of 表若干，谓语随 spiders 用复数。</p></details><p><strong>表达迁移：</strong> 为学校花园写三句观察记录，包含昆虫数量、可能解释和一个待控制变量。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We counted fewer insects near the old wall. Spiders may have contributed to the difference. We also need to compare the plants in both areas.</p><p>用 fewer 描述观察，用 may 保留解释空间，最后指出植物这一混杂因素。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">回看本课</a></p><h2 id="lesson-3-·-used-to、would-与过去状态" tabindex="-1">Lesson 3 · used to、would 与过去状态 <a class="header-anchor" href="#lesson-3-·-used-to、would-与过去状态" aria-label="Permalink to &quot;Lesson 3 · used to、would 与过去状态&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The village used to be quiet, but each summer guides would welcome new climbers.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Did the guide ___ to work alone?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> use</p><p><strong>解析：</strong> did 后接原形 use。</p></details><p><strong>表达迁移：</strong> 用三句介绍一个山村职业变化：过去状态、每年的习惯、现在的变化。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The village used to depend on farming. In summer, some residents would guide visitors along the ridge. Today, tourism provides another source of income.</p><p>状态用 used to，习惯用有时间背景的 would，现在用 today 切换时态。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">回看本课</a></p><h2 id="lesson-4-·-报告动词与认知距离" tabindex="-1">Lesson 4 · 报告动词与认知距离 <a class="header-anchor" href="#lesson-4-·-报告动词与认知距离" aria-label="Permalink to &quot;Lesson 4 · 报告动词与认知距离&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The participant was reported to have identified the colour, but the test did not rule out visual cues.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将“研究人员声称结果可重复”译为英语，使用 claim。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The researchers claim that the result can be replicated.</p><p><strong>解析：</strong> claim that 引出主张而不替读者保证其真实。</p></details><p><strong>表达迁移：</strong> 写三句评价一项“蒙眼认色”报道：归属主张、指出缺失条件、提出验证方式。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The report claims that a volunteer identified several colours while blindfolded. It does not describe how visual cues were excluded. Independent teams would need to repeat the test under controlled conditions.</p><p>三句分别承担归属、方法审查和验证要求，不把异常主张当作既定事实。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">回看本课</a></p><h2 id="lesson-5-·-让步从句与主句重心" tabindex="-1">Lesson 5 · 让步从句与主句重心 <a class="header-anchor" href="#lesson-5-·-让步从句与主句重心" aria-label="Permalink to &quot;Lesson 5 · 让步从句与主句重心&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Although Lena had little experience, the team took her proposal seriously.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Despite ___ little experience, he asked useful questions.（have）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> having</p><p><strong>解析：</strong> despite 后可接动名词短语。</p></details><p><strong>表达迁移：</strong> 用三句比较新人和资深同事，包含让步、具体贡献和合作建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Although our new colleague lacks experience, she notices problems we overlook. Her questions helped us simplify a form. We should combine fresh perspectives with practical knowledge.</p><p>让步后用具体表单案例支撑立场，避免对年龄群体作绝对评价。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">回看本课</a></p><h2 id="lesson-6-·-not-so-much-a-as-b-的纠正性对比" tabindex="-1">Lesson 6 · not so much A as B 的纠正性对比 <a class="header-anchor" href="#lesson-6-·-not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;Lesson 6 · not so much A as B 的纠正性对比&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The argument was not so much about the score as about respect.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例主要强调 score 还是 respect？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> respect</p><p><strong>解析：</strong> as 后的解释是重点。</p></details><p><strong>表达迁移：</strong> 为校际比赛争执写三句评论，指出主要问题并提出一个可执行改进。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The conflict was not so much about losing as about feeling ignored. Both captains should explain the decision calmly. A clear appeal process could reduce future arguments.</p><p>先重新界定冲突，再给出具体沟通和申诉措施，不把竞争必然等同于敌意。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">回看本课</a></p><h2 id="lesson-7-·-关系从句中的指代与功能说明" tabindex="-1">Lesson 7 · 关系从句中的指代与功能说明 <a class="header-anchor" href="#lesson-7-·-关系从句中的指代与功能说明" aria-label="Permalink to &quot;Lesson 7 · 关系从句中的指代与功能说明&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The device measures the delay between a signal and the echo that returns from the wall.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中 that 指 signal 还是 echo？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> echo</p><p><strong>解析：</strong> 关系从句紧接并限定 echo。</p></details><p><strong>表达迁移：</strong> 用三句解释一个回声测距演示，包括发射、返回和估算三个步骤。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A speaker sends a short pulse towards a wall. A sensor records the echo that comes back. The delay helps the device estimate the distance.</p><p>步骤顺序清楚；关系从句确定返回的信号，delay 把前两步与计算联系起来。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">回看本课</a></p><h2 id="lesson-8-·-情态动词的被动结构" tabindex="-1">Lesson 8 · 情态动词的被动结构 <a class="header-anchor" href="#lesson-8-·-情态动词的被动结构" aria-label="Permalink to &quot;Lesson 8 · 情态动词的被动结构&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Under our workshop rules, every sample must be checked before it is packed.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The labels must ___ replaced before delivery.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> be</p><p><strong>解析：</strong> 情态动词被动结构需要 be。</p></details><p><strong>表达迁移：</strong> 为虚构工作坊写三句包装检查说明：检查对象、缺陷处理、记录责任。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Each label must be checked before packing. Damaged boxes should be replaced. The supervisor must record the final inspection.</p><p>前两句突出对象，末句主动交代负责人；must 与 should 区分要求强度。</p></details><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">回看本课</a></p>',67)])])}const m=s(n,[["render",r]]);export{u as __pageData,m as default};
